import {CLASSROOM_API} from './classroom-config.js';
const svg=path=>`<svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${path}</svg>`;
const icons={learn:svg('<path d="M3 4h7a3 3 0 0 1 3 3v14a3 3 0 0 0-3-3H3z"/><path d="M21 4h-5a3 3 0 0 0-3 3v14a3 3 0 0 1 3-3h5z"/>'),home:svg('<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>'),homework:svg('<rect x="5" y="5" width="14" height="16" rx="2"/><path d="M9 3h6v4H9zM9 13l2 2 4-4"/>'),writing:svg('<path d="m15 4 5 5M4 20l1-6L16 3l5 5L10 19z"/>'),progress:svg('<path d="M4 4v16h17M8 15l4-5 4 2 5-7"/>'),people:svg('<circle cx="9" cy="7" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v1"/>'),more:svg('<path d="M4 6h16M4 12h16M4 18h16"/>')};
export function mobileLinks(teacher=false){return teacher?[['Home','#teacher/overview','home'],['Lessons','#teacher/lessons','learn'],['Work','#teacher/inbox','homework'],['Students','#teacher/students','people']]:[['Lessons','#lessons','learn'],['Homework','#homework','homework'],['Writing','#writing','writing'],['Progress','#progress','progress']];}
export function installInstructions(platform='other',inApp=false){const intro=inApp?'Open this page in Chrome on Android or Safari on iPhone first. ':'';if(platform==='ios')return intro+'In Safari, tap Share, choose Add to Home Screen, then tap Add. Leave Open as Web App enabled if it appears.';if(platform==='android')return intro+'In Chrome, open the ⋮ menu, choose Install app or Add to Home screen, then confirm Install or Add.';return 'Open the browser’s menu and look for Install app. On iPhone use Share → Add to Home Screen; on Android use Chrome’s ⋮ menu → Install app or Add to Home screen.';}
export function mobilePlatform(navigator){if(/iPhone|iPad|iPod/i.test(navigator.userAgent||'')||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1)return 'ios';return /Android/i.test(navigator.userAgent||'')?'android':'other';}
export function initMobileApp({win=window,doc=document,nav=navigator,api=CLASSROOM_API}={}){
 const teacher=!!api&&api.replace(/\/$/,'')===win.location.origin,platform=mobilePlatform(nav),inApp=/FBAN|FBAV|Instagram|; wv\)/i.test(nav.userAgent||''),media=win.matchMedia('(max-width: 800px)'),standalone=win.matchMedia('(display-mode: standalone)');
 let deferred=null,installed=standalone.matches||nav.standalone===true,menu=false,opener=null,registration=null;
 const sidebar=doc.querySelector('.sidebar'),main=doc.querySelector('.main-wrap'),top=doc.querySelector('.topbar'),originalSidebarRole=sidebar.getAttribute('role');
 const header=doc.createElement('div');header.className='mobile-brand';header.innerHTML='<button type="button" class="mobile-menu-button" aria-label="Open all sections" aria-controls="richmountMainMenu" aria-expanded="false">'+icons.more+'</button><a class="mobile-wordmark" href="'+(teacher?'#teacher/overview':'#home')+'"><img src="assets/richmount-logo.jpg" width="42" height="42" alt=""><span>Richmount<small>IELTS STUDIO'+(teacher?' · TEACHER':'')+'</small></span></a>';top.prepend(header);sidebar.id='richmountMainMenu';
 const install=doc.createElement('button');install.type='button';install.className='button soft mobile-install-button';install.textContent='Install app';install.hidden=installed;install.setAttribute('aria-label','Install Richmount on this device');top.querySelector('.top-actions').prepend(install);
 const close=doc.createElement('button');close.type='button';close.className='mobile-drawer-close button secondary';close.textContent='Close menu ×';sidebar.prepend(close);
 const backdrop=doc.createElement('button');backdrop.type='button';backdrop.className='mobile-menu-backdrop';backdrop.hidden=true;backdrop.tabIndex=-1;backdrop.setAttribute('aria-label','Close navigation');doc.body.append(backdrop);
 const bar=doc.createElement('nav');bar.className='mobile-tabbar';bar.setAttribute('aria-label',teacher?'Teacher app navigation':'Student app navigation');bar.innerHTML=mobileLinks(teacher).map(([label,href,icon])=>`<a href="${href}" data-mobile-route="${href}">${icons[icon]}<span>${label}</span></a>`).join('')+`<button type="button" data-mobile-more aria-controls="richmountMainMenu" aria-expanded="false">${icons.more}<span>More</span></button>`;doc.body.append(bar);
 const connection=doc.createElement('div');connection.className='mobile-connection';connection.setAttribute('role','status');connection.hidden=nav.onLine!==false;connection.textContent=teacher?'Offline · Reconnect to open your dashboard and class resources.':'Offline · Your saved drafts stay on this device. Reconnect for books, audio, AI reviews and sending work.';main.insertBefore(connection,doc.querySelector('#studentTaskBar')||doc.querySelector('#app'));
 const info=doc.createElement('dialog');info.id='richmountInstallDialog';info.className='mobile-install-dialog';info.innerHTML='<div class="eyebrow">RICHMOUNT · ON YOUR PHONE</div><h2>Your studio, one tap away.</h2><img class="mobile-install-icon" src="assets/app-icon-192.png" width="80" height="80" alt="Richmount education center"><p data-install-instructions></p><p class="small muted">Use your student code and password, or your teacher password in the app. Books, audio, AI reviews and submitting work need an internet connection.</p><div class="button-row"><a class="button" href="install.html">Full phone setup guide →</a><button type="button" class="button secondary" data-install-close>Close</button></div>';info.querySelector('[data-install-instructions]').textContent=installInstructions(platform,inApp);doc.body.append(info);

 const manifest=doc.querySelector('link[rel="manifest"]');if(teacher&&manifest)manifest.href='teacher.webmanifest';
 function drawer(open,button=opener){menu=!!open&&media.matches;if(button)opener=button;doc.body.classList.toggle('mobile-menu-open',menu);backdrop.hidden=!menu;main.inert=menu;bar.inert=menu;sidebar.inert=media.matches&&!menu;header.querySelector('button').setAttribute('aria-expanded',String(menu));bar.querySelector('button').setAttribute('aria-expanded',String(menu));if(menu){sidebar.setAttribute('role','dialog');sidebar.setAttribute('aria-modal','true');sidebar.setAttribute('aria-label','All Richmount sections');close.focus();}else{sidebar.removeAttribute('aria-modal');sidebar.removeAttribute('aria-label');if(originalSidebarRole)sidebar.setAttribute('role',originalSidebarRole);else sidebar.removeAttribute('role');if(button&&media.matches)button.focus();}}
 function current(){const hash=win.location.hash|| (teacher?'#teacher/overview':'#home');for(const a of bar.querySelectorAll('a')){const active=hash===a.getAttribute('href')||hash.startsWith(a.getAttribute('href')+'/');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}}
 header.querySelector('button').addEventListener('click',e=>drawer(!menu,e.currentTarget));bar.querySelector('button').addEventListener('click',e=>drawer(!menu,e.currentTarget));close.addEventListener('click',()=>drawer(false));backdrop.addEventListener('click',()=>drawer(false));sidebar.addEventListener('click',e=>{if(e.target.closest('a[href]')||e.target.closest('[data-session-logout]'))drawer(false);});
 doc.addEventListener('keydown',e=>{if(!menu)return;if(e.key==='Escape'){e.preventDefault();drawer(false);return;}if(e.key==='Tab'){const items=[...sidebar.querySelectorAll('button,a[href],input,select,textarea')].filter(n=>!n.hidden&&!n.disabled&&n.getClientRects().length);const first=items[0],last=items.at(-1);if(e.shiftKey&&doc.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&doc.activeElement===last){e.preventDefault();first?.focus();}}});
 win.addEventListener('hashchange',()=>{drawer(false,null);current();});media.addEventListener('change',()=>drawer(false,null));standalone.addEventListener('change',()=>{installed=standalone.matches||nav.standalone===true;install.hidden=installed;});
 win.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferred=e;if(!installed)install.hidden=false;});win.addEventListener('appinstalled',()=>{installed=true;deferred=null;install.hidden=true;info.close();});
 install.addEventListener('click',async()=>{if(deferred){const prompt=deferred;deferred=null;try{await prompt.prompt();const choice=await prompt.userChoice;if(choice.outcome==='accepted'){install.textContent='Installing…';return;}}catch{} }if(!installed&&!info.open)info.showModal();});info.querySelector('[data-install-close]').addEventListener('click',()=>info.close());
 win.addEventListener('offline',()=>{connection.hidden=false;});win.addEventListener('online',()=>{connection.hidden=true;});
 drawer(false,null);current();
 if('serviceWorker' in nav&&win.isSecureContext){nav.serviceWorker.register('/sw.js',{scope:'/',updateViaCache:'none'}).then(r=>{registration=r;function updateReady(){if(r.waiting&&nav.serviceWorker.controller&&!doc.querySelector('#richmountUpdateNotice')){const status=doc.createElement('p');status.id='richmountUpdateNotice';status.className='mobile-update-notice';status.setAttribute('role','status');status.textContent='An app update is ready. Finish your activity, then close and reopen Richmount.';main.prepend(status);}}updateReady();r.addEventListener('updatefound',()=>{const worker=r.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed')updateReady();});});}).catch(()=>{/* The online studio and manual home-screen installation remain available. */});}
 return {teacher,get installed(){return installed;},get registration(){return registration;},drawer,current};
}
if(typeof document!=='undefined'&&document.querySelector('.sidebar'))initMobileApp();
